import 'fdd_runtime.dart';
import 'harness.dart';

Future<Object?> signIn(Object? request, Object? deps) async {
  final __f = FddVerify.frame('bp-auth-login');
  __f.enter('NODE-AUTH-LOGIN-001');
  final Object? email = get(get(request, 'body'), 'email');
  final Object? emailCheck = checkEmail(email, 'email');
  final Object? password = get(get(request, 'body'), 'password');
  __f.enter('NODE-AUTH-LOGIN-006');
  if (!(bool_(get(emailCheck, 'valid')) && !isEmpty(password))) {
    __f.enter('NODE-AUTH-LOGIN-009');
    return obj([
      'status', 401.0,
      'body', obj([
        'error', bool_(get(emailCheck, 'valid')) ? get(checkRequired(password, 'password'), 'message') : get(emailCheck, 'message'),
      ]),
    ]);
  }
  __f.enter('NODE-AUTH-LOGIN-010');
  final Object? lookUpUser = await FddVerify.dep('userService', 'getUsersByEmail', 'NODE-AUTH-LOGIN-010', [obj(['query', omitNulls(obj(['email', email]))])]);
  final Object? status1 = get(lookUpUser, 'status');
  if (eq(status1, 200.0)) {
    __f.enter('NODE-AUTH-LOGIN-014');
    if (!eq(get(get(lookUpUser, 'body'), 'passwordHash'), format('hash:{password}', obj(['password', password])))) {
      __f.enter('NODE-AUTH-LOGIN-021');
      return obj(['status', 401.0, 'body', obj(['error', 'Invalid credentials'])]);
    }
    final Object? id = get(get(lookUpUser, 'body'), 'id');
    __f.enter('NODE-AUTH-LOGIN-018');
    await FddVerify.dep('eventBus', 'publishUserLoggedIn', 'NODE-AUTH-LOGIN-018', [obj(['userId', id])]);
    __f.enter('NODE-AUTH-LOGIN-019');
    return obj([
      'status', 200.0,
      'body', obj([
        'accessToken', format('TEST-TOKEN-{id}', obj(['id', id])),
        'refreshToken', 'REFRESH-TOKEN',
        'expiresIn', 3600.0,
        'tokenType', 'Bearer',
      ]),
    ]);
  } else if (eq(status1, 404.0)) {
    __f.enter('NODE-AUTH-LOGIN-022');
    return obj(['status', 401.0, 'body', obj(['error', 'Invalid credentials'])]);
  } else {
    __f.enter('NODE-AUTH-LOGIN-023');
    throw FddError('UPSTREAM_ERROR', 'User Service failed');
  }
}

