// Runtime for code generated by Rabbinatix from Logic Blueprints. Do not edit: it is regenerated on export.
// Every helper mirrors the simulator, so generated handlers behave exactly like their blueprints.
// Values are JSON values: Map<String, Object?> (keys in order), List<Object?>, String, double, bool and null.
// ignore_for_file: type=lint
import 'dart:convert';
import 'dart:math' as math;

/// An error with a code, like the simulator's errors (Throw nodes, DIVIDE_BY_ZERO, INVALID_JSON...).
class FddError implements Exception {
  final String code;
  final String message;

  FddError(Object? code, Object? message)
      : code = asString(code),
        message = asString(message);

  @override
  String toString() => '$code: $message';
}

/// An error that stops a handler: Try and Retry never catch it.
abstract class FddStop implements Exception {}

/// Converts between your own values and the JSON values the handlers take and return.
abstract final class FddJson {
  /// Plain values (maps, lists, numbers of any type, objects with toJson()) as JSON values.
  static Object? toValue(Object? value) {
    final v = value;
    if (v == null || v is String || v is bool) return v;
    if (v is num) return v.toDouble();
    if (v is Map) return <String, Object?>{for (final e in v.entries) e.key.toString(): toValue(e.value)};
    if (v is Iterable) return [for (final x in v) toValue(x)];
    if (v is Enum) return v.name;
    try {
      return toValue((v as dynamic).toJson());
    } on NoSuchMethodError {
      return v.toString();
    }
  }

  /// JSON text as JSON values; fails with FddError INVALID_JSON.
  static Object? parse(String text) => _JsonReader(text).document();

  /// JSON values as JSON text (JSON.stringify).
  static String stringify(Object? value) => json(value);
}

/// Strict JSON (what JSON.parse accepts); numbers become doubles.
class _JsonReader {
  final String s;
  int i = 0;

  _JsonReader(this.s);

  FddError _bad() => FddError('INVALID_JSON', 'Not valid JSON');

  Object? document() {
    _ws();
    final v = _value();
    _ws();
    if (i != s.length) throw _bad();
    return v;
  }

  void _ws() {
    while (i < s.length) {
      final c = s.codeUnitAt(i);
      if (c != 0x20 && c != 0x09 && c != 0x0a && c != 0x0d) break;
      i++;
    }
  }

  int _peek() {
    if (i >= s.length) throw _bad();
    return s.codeUnitAt(i);
  }

  Object? _value() {
    switch (_peek()) {
      case 0x7b:
        return _object();
      case 0x5b:
        return _array();
      case 0x22:
        return _string();
      case 0x74:
        return _word('true', true);
      case 0x66:
        return _word('false', false);
      case 0x6e:
        return _word('null', null);
      default:
        return _number();
    }
  }

  Object? _word(String w, Object? v) {
    if (!s.startsWith(w, i)) throw _bad();
    i += w.length;
    return v;
  }

  Map<String, Object?> _object() {
    final o = <String, Object?>{};
    i++;
    _ws();
    if (_peek() == 0x7d) {
      i++;
      return o;
    }
    while (true) {
      _ws();
      if (_peek() != 0x22) throw _bad();
      final k = _string();
      _ws();
      if (_peek() != 0x3a) throw _bad();
      i++;
      _ws();
      o[k] = _value();
      _ws();
      final c = _peek();
      i++;
      if (c == 0x7d) return o;
      if (c != 0x2c) throw _bad();
    }
  }

  List<Object?> _array() {
    final l = <Object?>[];
    i++;
    _ws();
    if (_peek() == 0x5d) {
      i++;
      return l;
    }
    while (true) {
      _ws();
      l.add(_value());
      _ws();
      final c = _peek();
      i++;
      if (c == 0x5d) return l;
      if (c != 0x2c) throw _bad();
    }
  }

  String _string() {
    i++;
    final out = <int>[];
    while (true) {
      final c = _peek();
      i++;
      if (c == 0x22) return String.fromCharCodes(out);
      if (c < 0x20) throw _bad();
      if (c != 0x5c) {
        out.add(c);
        continue;
      }
      final e = _peek();
      i++;
      switch (e) {
        case 0x22:
        case 0x5c:
        case 0x2f:
          out.add(e);
        case 0x62:
          out.add(0x08);
        case 0x66:
          out.add(0x0c);
        case 0x6e:
          out.add(0x0a);
        case 0x72:
          out.add(0x0d);
        case 0x74:
          out.add(0x09);
        case 0x75:
          if (i + 4 > s.length) throw _bad();
          var code = 0;
          for (var k = 0; k < 4; k++) {
            final d = _hex(s.codeUnitAt(i++));
            if (d < 0) throw _bad();
            code = code * 16 + d;
          }
          out.add(code);
        default:
          throw _bad();
      }
    }
  }

  double _number() {
    final start = i;
    if (i < s.length && s.codeUnitAt(i) == 0x2d) i++;
    if (i < s.length && s.codeUnitAt(i) == 0x30) {
      i++;
    } else if (!_digits()) {
      throw _bad();
    }
    if (i < s.length && s.codeUnitAt(i) == 0x2e) {
      i++;
      if (!_digits()) throw _bad();
    }
    if (i < s.length && (s.codeUnitAt(i) == 0x65 || s.codeUnitAt(i) == 0x45)) {
      i++;
      if (i < s.length && (s.codeUnitAt(i) == 0x2b || s.codeUnitAt(i) == 0x2d)) i++;
      if (!_digits()) throw _bad();
    }
    return double.parse(s.substring(start, i));
  }

  bool _digits() {
    final start = i;
    while (i < s.length && s.codeUnitAt(i) >= 0x30 && s.codeUnitAt(i) <= 0x39) {
      i++;
    }
    return i > start;
  }
}

int _hex(int c) {
  if (c >= 0x30 && c <= 0x39) return c - 0x30;
  if (c >= 0x41 && c <= 0x46) return c - 0x41 + 10;
  if (c >= 0x61 && c <= 0x66) return c - 0x61 + 10;
  return -1;
}

// ---------- the value model the generated code uses ----------

/// A condition: true only for true, else JavaScript truthiness.
bool bool_(Object? v) => v is bool ? v : truthy(v);

/// A number operand.
double num_(Object? v) => toNum(v);

/// o.name, null-safe: null when o is null or has no such field.
Object? get(Object? o, String name) => _key(o, name);

/// o[key], null-safe.
Object? item(Object? o, Object? k) => _key(o, k);

/// An object from key, value, key, value...
Map<String, Object?> obj([List<Object?> fields = const []]) {
  final o = <String, Object?>{};
  for (var i = 0; i + 1 < fields.length; i += 2) {
    o[fields[i] as String] = fields[i + 1];
  }
  return o;
}

/// a === b for strings, numbers, booleans and null (objects and lists: the same one).
bool eq(Object? a, Object? b) {
  if (a is num && b is num) return a.toDouble() == b.toDouble();
  if (a is String || a is bool || a == null) return a == b;
  return identical(a, b);
}

/// a % b (JavaScript's remainder: Dart's % is never negative).
double mod(double a, double b) => a.remainder(b);

List<Object?> iter(Object? v) => v is List<Object?> ? v : const [];

/// from, from + 1, ... while at most to.
Iterable<double> range(double from, double to) sync* {
  for (var i = from; i <= to; i++) {
    yield i;
  }
}

/// from, from + 1, ... without end (the loop stops itself).
Iterable<double> counting(double from) sync* {
  for (var i = from;; i++) {
    yield i;
  }
}

/// (index, item) of a list; the index is a number.
Iterable<(double, Object?)> indexed(Object? v) sync* {
  final l = iter(v);
  for (var i = 0; i < l.length; i++) {
    yield (i.toDouble(), l[i]);
  }
}

List<Object?> map(Object? items, Object? Function(Object?, Object?) fn) {
  final l = asArray(items);
  return [for (var i = 0; i < l.length; i++) fn(l[i], i.toDouble())];
}

List<Object?> filter(Object? items, bool Function(Object?, Object?) fn) {
  final l = asArray(items);
  return [for (var i = 0; i < l.length; i++) if (fn(l[i], i.toDouble())) l[i]];
}

Object? find(Object? items, bool Function(Object?, Object?) fn) {
  final l = asArray(items);
  for (var i = 0; i < l.length; i++) {
    if (fn(l[i], i.toDouble())) return l[i];
  }
  return null;
}

bool some(Object? items, bool Function(Object?, Object?) fn) {
  final l = asArray(items);
  for (var i = 0; i < l.length; i++) {
    if (fn(l[i], i.toDouble())) return true;
  }
  return false;
}

bool every(Object? items, bool Function(Object?, Object?) fn) {
  final l = asArray(items);
  for (var i = 0; i < l.length; i++) {
    if (!fn(l[i], i.toDouble())) return false;
  }
  return true;
}

Object? _key(Object? o, Object? k) {
  if (o is Map) return o[k is String ? k : jsString(k)];
  if (o is List) {
    if (k == 'length') return o.length.toDouble();
    final i = _index(k);
    return i >= 0 && i < o.length ? o[i] : null;
  }
  if (o is String) {
    if (k == 'length') return o.length.toDouble();
    final i = _index(k);
    return i >= 0 && i < o.length ? o[i] : null;
  }
  return null;
}

/// A list position, or -1.
int _index(Object? k) {
  double d;
  if (k is num) {
    d = k.toDouble();
  } else if (k is String && k.isNotEmpty && k.codeUnits.every((c) => c >= 0x30 && c <= 0x39)) {
    d = double.parse(k);
  } else {
    return -1;
  }
  return d >= 0 && d < 2147483647 && d.floorToDouble() == d ? d.toInt() : -1;
}

double _trunc(double d) => d.isFinite ? d.truncateToDouble() : d;

// ---------- JavaScript conversions ----------

/// A number as JavaScript's String(n) writes it.
String numText(double n) {
  if (n.isNaN) return 'NaN';
  if (n.isInfinite) return n > 0 ? 'Infinity' : '-Infinity';
  if (n == 0) return '0';
  // Dart's toString has the shortest digits that read back as the same double
  final parts = n.abs().toString().split('e');
  final mantissa = parts[0];
  final exp = parts.length > 1 ? int.parse(parts[1]) : 0;
  var digits = mantissa.replaceAll('.', '');
  final dot = mantissa.indexOf('.');
  var point = (dot < 0 ? mantissa.length : dot) + exp;
  while (digits.length > 1 && digits.startsWith('0')) {
    digits = digits.substring(1);
    point--;
  }
  while (digits.length > 1 && digits.endsWith('0')) {
    digits = digits.substring(0, digits.length - 1);
  }
  final k = digits.length;
  final sign = n < 0 ? '-' : '';
  if (k <= point && point <= 21) return sign + digits + '0' * (point - k);
  if (0 < point && point <= 21) return '$sign${digits.substring(0, point)}.${digits.substring(point)}';
  if (-6 < point && point <= 0) return '${sign}0.${'0' * -point}$digits';
  final x = point - 1;
  return '$sign${digits[0]}${k > 1 ? '.${digits.substring(1)}' : ''}e${x >= 0 ? '+' : '-'}${x.abs()}';
}

/// String(v).
String jsString(Object? v) {
  if (v == null) return 'null';
  if (v is bool) return v ? 'true' : 'false';
  if (v is num) return numText(v.toDouble());
  if (v is String) return v;
  if (v is List) return v.map((x) => x == null ? '' : jsString(x)).join(',');
  if (v is Map) return '[object Object]';
  if (v is FddError) return v.message;
  return v.toString();
}

/// JSON.stringify.
String json(Object? v) {
  final out = StringBuffer();
  _write(out, v);
  return out.toString();
}

void _write(StringBuffer out, Object? v) {
  if (v == null) {
    out.write('null');
  } else if (v is bool) {
    out.write(v ? 'true' : 'false');
  } else if (v is num) {
    final d = v.toDouble();
    out.write(d.isFinite ? numText(d) : 'null');
  } else if (v is String) {
    _quote(out, v);
  } else if (v is List) {
    out.write('[');
    for (var i = 0; i < v.length; i++) {
      if (i > 0) out.write(',');
      _write(out, v[i]);
    }
    out.write(']');
  } else if (v is Map) {
    out.write('{');
    var first = true;
    for (final k in _keyList(v)) {
      if (!first) out.write(',');
      first = false;
      _quote(out, k);
      out.write(':');
      _write(out, v[k]);
    }
    out.write('}');
  } else {
    _quote(out, v.toString());
  }
}

void _quote(StringBuffer out, String s) {
  out.write('"');
  for (var i = 0; i < s.length; i++) {
    final c = s.codeUnitAt(i);
    if (c == 0x22) {
      out.write(r'\"');
    } else if (c == 0x5c) {
      out.write(r'\\');
    } else if (c == 0x0a) {
      out.write(r'\n');
    } else if (c == 0x0d) {
      out.write(r'\r');
    } else if (c == 0x09) {
      out.write(r'\t');
    } else if (c == 0x08) {
      out.write(r'\b');
    } else if (c == 0x0c) {
      out.write(r'\f');
    } else if (c < 0x20 || _lone(s, i)) {
      out.write('\\u${c.toRadixString(16).padLeft(4, '0')}');
    } else {
      out.writeCharCode(c);
    }
  }
  out.write('"');
}

/// a surrogate without its other half (JSON.stringify escapes it)
bool _lone(String s, int i) {
  final c = s.codeUnitAt(i);
  if (c >= 0xd800 && c <= 0xdbff) return !(i + 1 < s.length && s.codeUnitAt(i + 1) >= 0xdc00 && s.codeUnitAt(i + 1) <= 0xdfff);
  if (c >= 0xdc00 && c <= 0xdfff) return !(i > 0 && s.codeUnitAt(i - 1) >= 0xd800 && s.codeUnitAt(i - 1) <= 0xdbff);
  return false;
}

/// JavaScript's white space and line terminators (what String.prototype.trim removes).
bool _jsSpace(int c) =>
    c == 0x20 || (c >= 0x09 && c <= 0x0d) || c == 0xa0 || c == 0x1680 || (c >= 0x2000 && c <= 0x200a) || c == 0x2028 || c == 0x2029 ||
    c == 0x202f || c == 0x205f || c == 0x3000 || c == 0xfeff;

String _jsTrim(String s) {
  var i = 0;
  var j = s.length;
  while (i < j && _jsSpace(s.codeUnitAt(i))) {
    i++;
  }
  while (j > i && _jsSpace(s.codeUnitAt(j - 1))) {
    j--;
  }
  return s.substring(i, j);
}

final _decimal = RegExp(r'^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$');

/// Number(v).
double jsNumber(Object? v) {
  if (v == null) return 0;
  if (v is bool) return v ? 1 : 0;
  if (v is num) return v.toDouble();
  if (v is String) {
    final t = _jsTrim(v);
    if (t.isEmpty) return 0;
    if (t.length > 2 && t[0] == '0' && 'xXoObB'.contains(t[1])) {
      final radix = 'xX'.contains(t[1]) ? 16 : 'oO'.contains(t[1]) ? 8 : 2;
      var acc = 0.0;
      for (final c in t.substring(2).codeUnits) {
        final d = _hex(c);
        if (d < 0 || d >= radix) return double.nan;
        acc = acc * radix + d;
      }
      return acc;
    }
    if (t == 'Infinity' || t == '+Infinity') return double.infinity;
    if (t == '-Infinity') return double.negativeInfinity;
    return _decimal.hasMatch(t) ? double.parse(t) : double.nan;
  }
  if (v is List) {
    if (v.isEmpty) return 0;
    if (v.length == 1) {
      final x = v[0];
      return x is List || x is Map ? double.nan : x == null ? 0 : jsNumber(x);
    }
  }
  return double.nan;
}

Object? _prim(Object? x) => x is List || x is Map ? jsString(x) : x;

bool _lt(Object? a, Object? b) => a is String && b is String ? a.compareTo(b) < 0 : jsNumber(_prim(a)) < jsNumber(_prim(b));

// ---------- values ----------

/// Branch semantics: "" and "false" are false.
bool truthy(Object? v) {
  if (v == null) return false;
  if (v is String) return v.isNotEmpty && v != 'false';
  if (v is bool) return v;
  if (v is num) return v != 0 && !v.isNaN;
  return true;
}

/// null, "", [] or {}.
bool isEmpty(Object? v) {
  if (v == null) return true;
  if (v is String) return _jsTrim(v).isEmpty;
  if (v is List) return v.isEmpty;
  if (v is Map) return v.isEmpty;
  return false;
}

/// null or missing.
bool isNull(Object? v) => v == null;

/// Structural equality (objects and arrays by value).
bool deepEqual(Object? a, Object? b) {
  if (a is num && b is num) return a.toDouble() == b.toDouble() || (a.isNaN && b.isNaN);
  if (a is List && b is List) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (a is Map && b is Map) return a.length == b.length && a.keys.every((k) => b.containsKey(k) && deepEqual(a[k], b[k]));
  return eq(a, b);
}

/// -1, 0 or 1.
double compare(Object? a, Object? b) => deepEqual(a, b) ? 0 : _lt(a, b) ? -1 : 1;

/// An arithmetic operand: numbers as is, anything else through Number().
double toNum(Object? v) => v is num ? v.toDouble() : jsNumber(v);

/// Fails on zero.
double divide(Object? a, Object? b) {
  if (toNum(b) == 0) throw FddError('DIVIDE_BY_ZERO', 'Division by zero');
  return toNum(a) / toNum(b);
}

/// The value if it is an array, else [].
List<Object?> asArray(Object? v) => v is List<Object?> ? v : <Object?>[];

/// A query found something (not null, not an empty list).
bool isFound(Object? v) => v is List ? v.isNotEmpty : v != null;

/// Drops null entries (query and header maps).
Map<String, Object?> omitNulls(Object? o) => {
      if (o is Map<String, Object?>)
        for (final e in o.entries)
          if (e.value != null) e.key: e.value
    };

/// a ?? b with b evaluated first (b has no effects).
Object? orElse(Object? a, Object? b) => a ?? b;

// ---------- paths & objects ----------

/// A path that isn't there (JavaScript's undefined): left out of objects, like JSON.stringify does.
class _Missing {
  const _Missing();
}

const _missing = _Missing();

class _Seg {
  final String? name;
  final int index;

  const _Seg(this.name, this.index);

  String get key => name ?? '$index';

  Object get value => name ?? index.toDouble();
}

final _segment = RegExp(r'([^\[\]]+)|\[(\d+)\]');

/// user.roles[0].name
List<_Seg> _segments(String path) => [
      for (final part in path.split('.'))
        if (part.isNotEmpty)
          for (final m in _segment.allMatches(part)) m.group(1) != null ? _Seg(m.group(1), -1) : _Seg(null, int.tryParse(m.group(2)!) ?? 2147483647)
    ];

bool _unsafe(List<_Seg> segs) => segs.any((s) => s.name == '__proto__' || s.name == 'constructor' || s.name == 'prototype');

/// The path exists (its value may be null).
bool hasPath(Object? value, Object? path) {
  final p = str(path);
  if (p.isEmpty || p == r'$') return true;
  final segs = _segments(p);
  if (_unsafe(segs)) return false;
  var cur = value;
  for (final s in segs) {
    if (cur is Map) {
      if (!cur.containsKey(s.key)) return false;
      cur = cur[s.key];
    } else if (cur is List) {
      if (s.name == 'length') {
        cur = cur.length.toDouble();
      } else if (s.name == null && s.index < cur.length) {
        cur = cur[s.index];
      } else {
        return false;
      }
    } else if (cur is String) {
      if (s.name == 'length') {
        cur = cur.length.toDouble();
      } else if (s.name == null && s.index < cur.length) {
        cur = cur[s.index];
      } else {
        return false;
      }
    } else {
      return false;
    }
  }
  return true;
}

/// Reads a nested value; null when a step is missing.
Object? getPath(Object? value, Object? path) {
  final p = str(path);
  if (p.isEmpty || p == r'$') return value;
  final segs = _segments(p);
  if (_unsafe(segs)) return null;
  var cur = value;
  for (final s in segs) {
    if (cur == null) return null;
    cur = _key(cur, s.value);
  }
  return cur;
}

Object? _lookup(Object? value, String path) => hasPath(value, path) ? getPath(value, path) : _missing;

bool _container(Object? v) => v is List || v is Map;

Object? _shallowCopy(Object? v) => v is List<Object?> ? List<Object?>.of(v) : v is Map<String, Object?> ? Map<String, Object?>.of(v) : v;

Object _emptyFor(_Seg next) => next.name == null ? <Object?>[] : <String, Object?>{};

/// A copy with a nested value set.
Object? setPath(Object? value, Object? path, Object? v) {
  final segs = _segments(str(path));
  if (segs.isEmpty) return v;
  final root = _container(value) ? _shallowCopy(value) : <String, Object?>{};
  if (_unsafe(segs)) return root;
  _setIn(root, segs, 0, v);
  return root;
}

/// Sets segs[i..] in cur, a fresh copy.
void _setIn(Object? cur, List<_Seg> segs, int i, Object? v) {
  final s = segs[i];
  final last = i == segs.length - 1;
  if (cur is List<Object?>) {
    if (s.name != null) return;
    while (cur.length <= s.index) {
      cur.add(null);
    }
    if (last) {
      if (v is! _Missing) cur[s.index] = v;
      return;
    }
    var next = _shallowCopy(cur[s.index]);
    if (!_container(next)) next = _emptyFor(segs[i + 1]);
    cur[s.index] = next;
    _setIn(next, segs, i + 1, v);
    return;
  }
  final d = cur as Map<String, Object?>;
  if (last) {
    if (v is! _Missing) d[s.key] = v;
    return;
  }
  var next = d.containsKey(s.key) ? _shallowCopy(d[s.key]) : null;
  if (!_container(next)) next = _emptyFor(segs[i + 1]);
  d[s.key] = next;
  _setIn(next, segs, i + 1, v);
}

Object? _deepClone(Object? v) {
  if (v is List) return <Object?>[for (final x in v) _deepClone(x)];
  if (v is Map) return <String, Object?>{for (final e in v.entries) e.key as String: _deepClone(e.value)};
  return v;
}

/// A copy without a nested value.
Object? removePath(Object? value, Object? path) {
  final segs = _segments(str(path));
  if (segs.isEmpty || !_container(value)) return value;
  final clone = _deepClone(value);
  if (_unsafe(segs)) return clone;
  _removeIn(clone, segs, 0);
  return clone;
}

void _removeIn(Object? cur, List<_Seg> segs, int i) {
  final s = segs[i];
  if (i == segs.length - 1) {
    if (cur is List && s.name == null && s.index < cur.length) {
      cur.removeAt(s.index);
    } else if (cur is Map) {
      cur.remove(s.key);
    }
    return;
  }
  final next = cur is Map ? cur[s.key] : cur is List && s.name == null && s.index < cur.length ? cur[s.index] : null;
  if (_container(next)) _removeIn(next, segs, i + 1);
}

Map<String, Object?> _spread(Object? v) {
  if (v is Map<String, Object?>) return v;
  if (v is List) return {for (var i = 0; i < v.length; i++) '$i': v[i]};
  if (v is String) return {for (var i = 0; i < v.length; i++) '$i': v[i]};
  return const {};
}

/// Shallow merge, B over A.
Map<String, Object?> merge(Object? a, Object? b) => {..._spread(a), ..._spread(b)};

/// A new object: target path from source path.
Object? transform(Object? source, Object? mapping) {
  Object? out = <String, Object?>{};
  for (final pair in asArray(mapping)) {
    final p = asArray(pair);
    out = setPath(out, p.isNotEmpty ? p[0] : null, _lookup(source, str(p.length > 1 ? p[1] : null)));
  }
  return out;
}

final _placeholder = RegExp(r'\{\{\s*([^}]+?)\s*\}\}');
final _wholePlaceholder = RegExp(r'^\{\{\s*([^}]+?)\s*\}\}$');

/// Fills {{path}} placeholders from data.
Object? template(Object? value, Object? data) {
  final r = _fill(value, data);
  return r is _Missing ? null : r;
}

Object? _fill(Object? value, Object? data) {
  if (value is String) {
    final whole = _wholePlaceholder.firstMatch(value);
    if (whole != null) return _lookup(data, whole.group(1)!);
    return value.replaceAllMapped(_placeholder, (m) {
      final r = getPath(data, m.group(1));
      return r == null ? '' : _container(r) ? json(r) : jsString(r);
    });
  }
  if (value is List) {
    return <Object?>[
      for (final x in value)
        switch (_fill(x, data)) { _Missing() => null, final z => z }
    ];
  }
  if (value is Map) {
    final o = <String, Object?>{};
    for (final e in value.entries) {
      final z = _fill(e.value, data);
      if (z is! _Missing) o[e.key as String] = z;
    }
    return o;
  }
  return value;
}

/// JSON.parse that fails with INVALID_JSON.
Object? parseJson(Object? text) => FddJson.parse(jsString(text));

/// The { code, message } a Catch or Failed pin receives; an FddStop is thrown on.
Map<String, Object?> toError(Object e) {
  if (e is FddStop) throw e;
  if (e is FddError) return obj(['code', e.code, 'message', e.message]);
  return obj(['code', 'RUNTIME_ERROR', 'message', e.toString()]);
}

// ---------- strings ----------

/// A string operand: null is "".
String str(Object? v) => v == null ? '' : jsString(v);

/// String(v), like a Switch compares.
String asString(Object? v) => jsString(v);

bool contains(Object? text, Object? search) => str(text).contains(str(search));

bool startsWith(Object? text, Object? prefix) => str(text).startsWith(str(prefix));

bool endsWith(Object? text, Object? suffix) => str(text).endsWith(str(suffix));

String trim(Object? text) => _jsTrim(str(text));

String lower(Object? text) => str(text).toLowerCase();

String upper(Object? text) => str(text).toUpperCase();

double strLength(Object? text) => str(text).length.toDouble();

String concat(Object? a, Object? b) => str(a) + str(b);

/// text split on a separator (an empty one splits every UTF-16 unit, like JavaScript)
List<String> _splitUnits(String t, String s) => s.isEmpty ? [for (var i = 0; i < t.length; i++) t[i]] : t.split(s);

String replaceAll(Object? text, Object? search, Object? replacement) => _splitUnits(str(text), str(search)).join(str(replacement));

/// An empty separator splits on ",".
List<Object?> split(Object? text, Object? separator) {
  final s = str(separator);
  return List<Object?>.of(_splitUnits(str(text), s.isEmpty ? ',' : s));
}

String join(Object? items, Object? separator) => asArray(items).map(str).join(str(separator));

RegExp _rx(String pattern, String flags) {
  for (final c in flags.split('')) {
    if (!'gimsuyd'.contains(c)) throw FddError('INVALID_REGEX', 'Invalid pattern $pattern');
  }
  try {
    return RegExp(pattern, caseSensitive: !flags.contains('i'), multiLine: flags.contains('m'), dotAll: flags.contains('s'), unicode: flags.contains('u'));
  } on FormatException {
    throw FddError('INVALID_REGEX', 'Invalid pattern $pattern');
  }
}

Map<String, Object?> regexMatch(Object? text, Object? pattern, Object? flags) {
  final m = _rx(str(pattern), str(flags)).firstMatch(str(text));
  return obj(['matches', m != null, 'groups', <Object?>[if (m != null) for (var i = 1; i <= m.groupCount; i++) m.group(i)]]);
}

final _named = RegExp(r'\{(\w+)\}');

/// Fills {name} placeholders.
String format(Object? template, Object? values) => str(template).replaceAllMapped(_named, (m) => str(get(values, m.group(1)!)));

// ---------- collections ----------

double len(Object? a) => a is List ? a.length.toDouble() : 0;

Object? at(Object? a, Object? i) => _key(asArray(a), toNum(i));

/// A copy with the item appended.
List<Object?> append(Object? a, Object? item) => [...asArray(a), item];

/// Deep-equal membership.
bool includes(Object? a, Object? item) => asArray(a).any((x) => deepEqual(x, item));

double sum(Object? a, Object? path) {
  final p = str(path);
  var t = 0.0;
  for (final x in asArray(a)) {
    t += toNum(p.isNotEmpty ? getPath(x, p) : x);
  }
  return t;
}

List<Object?> sortBy(Object? a, Object? path, Object? desc) {
  final dir = truthy(desc) ? -1 : 1;
  final p = str(path);
  // a stable merge sort, like Array.prototype.sort (it never fails on an inconsistent order)
  return _mergeSort(asArray(a), (x, y) {
    final u = p.isNotEmpty ? getPath(x, p) : x;
    final w = p.isNotEmpty ? getPath(y, p) : y;
    return _lt(u, w) ? -dir : _lt(w, u) ? dir : 0;
  });
}

List<Object?> _mergeSort(List<Object?> l, int Function(Object?, Object?) c) {
  if (l.length < 2) return List<Object?>.of(l);
  final a = _mergeSort(l.sublist(0, l.length ~/ 2), c);
  final b = _mergeSort(l.sublist(l.length ~/ 2), c);
  final out = <Object?>[];
  var i = 0;
  var j = 0;
  while (i < a.length && j < b.length) {
    out.add(c(b[j], a[i]) < 0 ? b[j++] : a[i++]);
  }
  return out..addAll(a.sublist(i))..addAll(b.sublist(j));
}

/// One item at a time (deterministic order).
Future<List<Object?>> mapAsync(Object? items, Future<Object?> Function(Object?, Object?) fn) async {
  final l = asArray(items);
  return [for (var i = 0; i < l.length; i++) await fn(l[i], i.toDouble())];
}

Future<List<Object?>> filterAsync(Object? items, Future<Object?> Function(Object?, Object?) fn) async {
  final l = asArray(items);
  return [for (var i = 0; i < l.length; i++) if (truthy(await fn(l[i], i.toDouble()))) l[i]];
}

Future<Object?> findAsync(Object? items, Future<Object?> Function(Object?, Object?) fn) async {
  final l = asArray(items);
  for (var i = 0; i < l.length; i++) {
    if (truthy(await fn(l[i], i.toDouble()))) return l[i];
  }
  return null;
}

Future<bool> someAsync(Object? items, Future<Object?> Function(Object?, Object?) fn) async {
  final l = asArray(items);
  for (var i = 0; i < l.length; i++) {
    if (truthy(await fn(l[i], i.toDouble()))) return true;
  }
  return false;
}

Future<bool> everyAsync(Object? items, Future<Object?> Function(Object?, Object?) fn) async {
  final l = asArray(items);
  for (var i = 0; i < l.length; i++) {
    if (!truthy(await fn(l[i], i.toDouble()))) return false;
  }
  return true;
}

/// The first item, or null.
Object? first(Object? a) => asArray(a).firstOrNull;

/// The last item, or null.
Object? last(Object? a) => asArray(a).lastOrNull;

/// Groups items by the text of a path: { value: [items] }.
Map<String, Object?> groupBy(Object? a, Object? path) {
  final p = str(path);
  final groups = <String, Object?>{};
  for (final x in asArray(a)) {
    final k = toStringValue(p.isNotEmpty ? getPath(x, p) : x);
    (groups.putIfAbsent(k, () => <Object?>[]) as List<Object?>).add(x);
  }
  return {for (final k in _keyList(groups)) k: groups[k]};
}

/// The mean of numbers or of a path; 0 for an empty list.
double average(Object? a, Object? path) {
  final n = asArray(a).length;
  return n == 0 ? 0 : sum(a, path) / n;
}

// ---------- validation: every check returns { valid, message } ----------

Map<String, Object?> _valid() => obj(['valid', true, 'message', '']);

Map<String, Object?> _invalid(String message) => obj(['valid', false, 'message', message]);

Map<String, Object?> checkRequired(Object? v, Object? field) => isEmpty(v) ? _invalid('${str(field)} is required') : _valid();

final _email = RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$');

Map<String, Object?> checkEmail(Object? v, Object? field) => v is String && _email.hasMatch(v) ? _valid() : _invalid('${str(field)} must be a valid email');

String _valueType(Object? v) {
  if (v == null) return 'null';
  if (v is List) return 'array';
  if (v is num) return v.isFinite && v.floorToDouble() == v ? 'integer' : 'number';
  if (v is String) return 'string';
  if (v is bool) return 'boolean';
  return 'object';
}

Map<String, Object?> checkType(Object? v, Object? type, Object? field) {
  final vt = _valueType(v);
  final t = str(type);
  return vt == t || (t == 'number' && vt == 'integer') ? _valid() : _invalid('${str(field)} must be $t');
}

/// The first problem of a value against a shape, or null.
String? _checkValue(Object? v, Object? s, String path) {
  if (s is! Map || eq(get(s, 'type'), 'any')) return null;
  final type = get(s, 'type');
  if (v == null) return truthy(get(s, 'nullable')) || eq(type, 'null') ? null : '$path is null';
  final t = _valueType(v);
  if (eq(type, 'number') && (t == 'integer' || t == 'number')) return null;
  if (!eq(type, t)) return '$path: expected ${str(type)}, got $t';
  final en = get(s, 'enum');
  if (en is List && en.isNotEmpty && !includes(en, v)) return '$path: ${json(v)} is not one of ${en.map(jsString).join(', ')}';
  final props = get(s, 'properties');
  if (props is Map && v is Map) {
    for (final e in props.entries) {
      if (!v.containsKey(e.key)) {
        if (truthy(get(e.value, 'required'))) return '$path.${e.key} is missing';
        continue;
      }
      final p = _checkValue(v[e.key], e.value, '$path.${e.key}');
      if (p != null) return p;
    }
  }
  if (v is List) {
    for (var i = 0; i < v.length; i++) {
      final p = _checkValue(v[i], get(s, 'items'), '$path[$i]');
      if (p != null) return p;
    }
  }
  return null;
}

Map<String, Object?> checkShape(Object? v, Object? shape, Object? field) {
  final p = _checkValue(v, shape, str(field));
  return p != null ? _invalid(p) : _valid();
}

Map<String, Object?> checkRange(Object? v, Object? lo, Object? hi, Object? field) {
  if (v is! num) return _invalid('${str(field)} must be a number');
  if (lo != null && !eq(lo, '') && v < toNum(lo)) return _invalid('${str(field)} must be ≥ ${jsString(lo)}');
  if (hi != null && !eq(hi, '') && v > toNum(hi)) return _invalid('${str(field)} must be ≤ ${jsString(hi)}');
  return _valid();
}

Map<String, Object?> checkRegex(Object? v, Object? pattern, Object? field) {
  final RegExp re;
  try {
    re = RegExp(str(pattern));
  } on FormatException {
    return _invalid('invalid pattern');
  }
  return re.hasMatch(str(v)) ? _valid() : _invalid('${str(field)} has an invalid format');
}

Map<String, Object?> checkPassword(Object? v, Object? policy, Object? field) {
  final p = str(v);
  final min = toNum(get(policy, 'minLength'));
  if (p.length < min) return _invalid('${str(field)} must be at least ${numText(min)} characters');
  if (truthy(get(policy, 'requireDigit')) && !p.codeUnits.any((c) => c >= 0x30 && c <= 0x39)) return _invalid('${str(field)} must contain a digit');
  if (truthy(get(policy, 'requireUpper')) && !p.codeUnits.any((c) => c >= 0x41 && c <= 0x5a)) return _invalid('${str(field)} must contain an uppercase letter');
  return _valid();
}

// ---------- conversion ----------

/// Objects become JSON.
String toStringValue(Object? v) => _container(v) ? json(v) : v == null ? '' : jsString(v);

/// Not a number is 0.
double toNumber(Object? v) {
  final n = jsNumber(v);
  return n.isNaN ? 0 : n;
}

bool isNumeric(Object? v) => !jsNumber(v).isNaN;

bool toBoolean(Object? v) => truthy(v);

/// string, integer, number, boolean, object, array or null.
String typeOf(Object? v) => _valueType(v);

// ---------- math ----------

/// Math.min and Math.max: NaN wins, -0 is below 0.
double _jsMin(double a, double b) => a.isNaN || b.isNaN ? double.nan : a == b ? (a.isNegative ? a : b) : a < b ? a : b;

double _jsMax(double a, double b) => a.isNaN || b.isNaN ? double.nan : a == b ? (a.isNegative ? b : a) : a > b ? a : b;

/// 0-15 decimals, halves up.
double round(Object? v, Object? decimals) {
  final x = toNum(v);
  final d = _trunc(toNum(decimals));
  final f = math.pow(10, d.isFinite ? d.clamp(0, 15) : 0).toDouble();
  final y = x * f + 0.5;
  return y.isFinite ? y.floorToDouble() / f : x;
}

double floor(Object? v) {
  final x = toNum(v);
  return x.isFinite ? x.floorToDouble() : x;
}

double ceil(Object? v) {
  final x = toNum(v);
  return x.isFinite ? x.ceilToDouble() : x;
}

double abs(Object? v) => toNum(v).abs();

double min(Object? a, Object? b) => _jsMin(toNum(a), toNum(b));

double max(Object? a, Object? b) => _jsMax(toNum(a), toNum(b));

/// Keeps the value between lo and hi.
double clamp(Object? v, Object? lo, Object? hi) => _jsMin(_jsMax(toNum(v), toNum(lo)), toNum(hi));

/// JavaScript's ** (1 ** Infinity is NaN).
double power(Object? a, Object? b) {
  final x = toNum(a);
  final y = toNum(b);
  return y.isNaN || (x.abs() == 1 && y.isInfinite) ? double.nan : math.pow(x, y).toDouble();
}

double sqrt(Object? v) => math.sqrt(toNum(v));

// ---------- text and encoding ----------

/// A slice position: negative counts from the end, clamped to 0..n.
int _relIndex(Object? v, int n) {
  final r = _trunc(toNum(v));
  if (r.isNaN) return 0;
  return r < 0 ? math.max(n + r, 0).toInt() : math.min(r, n.toDouble()).toInt();
}

/// Like String.prototype.slice; a null end means the end of the text.
String substring(Object? text, Object? start, Object? end) {
  final t = str(text);
  final i = _relIndex(start, t.length);
  final j = end == null ? t.length : _relIndex(end, t.length);
  return j <= i ? '' : t.substring(i, j);
}

double indexOf(Object? text, Object? search) => str(text).indexOf(str(search)).toDouble();

String _pad(Object? text, Object? length, Object? fill, bool atStart) {
  final t = str(text);
  final n = _trunc(toNum(length));
  if (n > 100000) throw FddError('INVALID_LENGTH', 'Length must be at most 100000');
  final f = fill == null ? ' ' : str(fill);
  if (n.isNaN || n <= t.length || f.isEmpty) return t;
  final need = n.toInt() - t.length;
  final p = (f * (need ~/ f.length + 1)).substring(0, need);
  return atStart ? p + t : t + p;
}

String padStart(Object? text, Object? length, Object? fill) => _pad(text, length, fill, true);

String padEnd(Object? text, Object? length, Object? fill) => _pad(text, length, fill, false);

/// UTF-8 text as Base64.
String base64Encode(Object? text) => base64.encode(utf8.encode(str(text)));

final _base64Text = RegExp(r'^[A-Za-z0-9+/]*$');

/// Base64 as UTF-8 text; fails with INVALID_BASE64.
String base64Decode(Object? text) {
  var t = str(text).replaceAll(RegExp(r'[\t\n\f\r ]+'), '');
  if (t.length % 4 == 0) t = t.replaceFirst(RegExp(r'={1,2}$'), '');
  if (t.length % 4 == 1 || !_base64Text.hasMatch(t)) throw FddError('INVALID_BASE64', 'Not valid Base64');
  try {
    return utf8.decode(base64.decode(t + '=' * ((4 - t.length % 4) % 4)), allowMalformed: true);
  } on FormatException {
    throw FddError('INVALID_BASE64', 'Not valid Base64');
  }
}

/// Fixed decimals (halves up) and a thousands separator; fails with INVALID_NUMBER.
String formatNumber(Object? value, Object? decimals, Object? thousands, Object? point) {
  final d0 = _trunc(toNum(decimals));
  final d = d0.isFinite ? d0.clamp(0, 15).toInt() : 0;
  final r = round(value, d.toDouble());
  if (!r.isFinite || r.abs() >= 1e21) throw FddError('INVALID_NUMBER', 'Not a number that can be formatted');
  final text = r.abs().toStringAsFixed(d);
  final dot = text.indexOf('.');
  var whole = dot < 0 ? text : text.substring(0, dot);
  final frac = dot < 0 ? '' : text.substring(dot + 1);
  final sign = r < 0 && (whole + frac).codeUnits.any((c) => c >= 0x31 && c <= 0x39) ? '-' : '';
  final groups = <String>[];
  while (whole.length > 3) {
    groups.insert(0, whole.substring(whole.length - 3));
    whole = whole.substring(0, whole.length - 3);
  }
  groups.insert(0, whole);
  return sign + groups.join(str(thousands)) + (frac.isNotEmpty ? str(point) + frac : '');
}

/// sha256, sha1 or md5 ("SHA-256" too); fails with INVALID_ALGORITHM.
String _digestAlgorithm(Object? a) {
  final k = _jsTrim(str(a)).toLowerCase().replaceAll('-', '');
  if (k != 'sha256' && k != 'sha1' && k != 'md5') throw FddError('INVALID_ALGORITHM', 'Unknown hash algorithm "${str(a)}" (use sha256, sha1 or md5)');
  return k;
}

/// hex or base64; fails with INVALID_ENCODING.
String _encodeDigest(List<int> b, Object? encoding) {
  switch (_jsTrim(str(encoding)).toLowerCase()) {
    case 'hex':
      return b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();
    case 'base64':
      return base64.encode(b);
    default:
      throw FddError('INVALID_ENCODING', 'Unknown encoding "${str(encoding)}" (use hex or base64)');
  }
}

List<int> _digest(String algorithm, List<int> m) => algorithm == 'sha256' ? _Digest.sha256(m) : algorithm == 'sha1' ? _Digest.sha1(m) : _Digest.md5(m);

/// SHA-256, SHA-1 or MD5 of UTF-8 text, as hex or Base64.
String hash(Object? text, Object? algorithm, Object? encoding) => _encodeDigest(_digest(_digestAlgorithm(algorithm), utf8.encode(str(text))), encoding);

/// The HMAC of UTF-8 text with a UTF-8 key, as hex or Base64.
String hmac(Object? text, Object? key, Object? algorithm, Object? encoding) {
  final a = _digestAlgorithm(algorithm);
  var k = utf8.encode(str(key)).toList();
  if (k.length > 64) k = _digest(a, k);
  k = [...k, ...List.filled(64 - k.length, 0)];
  final inner = _digest(a, [for (final x in k) x ^ 0x36, ...utf8.encode(str(text))]);
  return _encodeDigest(_digest(a, [for (final x in k) x ^ 0x5c, ...inner]), encoding);
}

/// SHA-256, SHA-1 and MD5 (the core libraries have no hashing).
abstract final class _Digest {
  static const _mask = 0xffffffff;

  static List<int> _pad(List<int> m, bool bigEndian) {
    final b = [...m, 0x80];
    while (b.length % 64 != 56) {
      b.add(0);
    }
    final bits = m.length * 8;
    for (var i = 0; i < 8; i++) {
      b.add((bigEndian ? bits >> (56 - 8 * i) : bits >> (8 * i)) & 0xff);
    }
    return b;
  }

  static int _rotl(int x, int n) => ((x << n) | (x >> (32 - n))) & _mask;

  static int _be(List<int> b, int i) => (b[i] << 24) | (b[i + 1] << 16) | (b[i + 2] << 8) | b[i + 3];

  static List<int> _bytes(List<int> words, bool bigEndian) => [
        for (final w in words)
          for (var k = 0; k < 4; k++) (bigEndian ? w >> (24 - 8 * k) : w >> (8 * k)) & 0xff
      ];

  static const _k256 = [
